contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable {
        bool reverted;
        c.SetMinSum(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint m = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(!reverted && m == v);
    }

    receive() external payable {}
}

