        c = new MONEY_BOX();
    }

    function _run(uint256 v) internal {
        bool reverted;
        try c.SetMinSum(v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 m;
        try c.MinSum() returns (uint256 __r) { m = __r; } catch { return; }
        assertTrue(!reverted && m == v);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

